import base64
import zlib

data1 = """"""

print("Decoding data...")
try:
    raw1 = base64.b64decode(data1)
    decomp1 = zlib.decompress(raw1, 16 + zlib.MAX_WBITS)
    text1 = decomp1.decode('utf-8')
    with open('/tmp/page1.html', 'w', encoding='utf-8') as f:
        f.write(text1)
    print("Page 1 decoded successfully! Length:", len(text1))
except Exception as e:
    print("Error decoding:", e)
